			}
			return identity;
		},
		displacementPolicies: Object.freeze({ message: "rebase" as const }),
		migration: Object.freeze({
			canonicalStateBytes: canonicalChatStateBytes,
			prepare: prepareChatMigration,
		}),
		projectAcceptedOperations: projectChat,
